//! Copies the option table generated by Nix into `OUT_DIR`.
//!
//! The table lives in `assets/tor-options.nix` and is generated by
//! `nix/scripts/gen-options.py`. This build script does NOT generate it — it
//! only locates the finished file. Generating here would reimplement Nix logic
//! (invariant 5) and would leave the source of truth.
//!
//! It is `crates/ronoctua-syncthing/build.rs`, letter for letter except the
//! variable: the two tables come out of the same generator now.

use std::env;
use std::fs;
use std::path::PathBuf;

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_TOR_OPTIONS_RS");
    let generated = env::var("RONOCTUA_TOR_OPTIONS_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_TOR_OPTIONS_RS is not set.\n\
             The Tor option table is generated by Nix from assets/tor-options.nix.\n\
             Build inside `nix develop`, or set the variable to a generated options.rs."
        )
    });
    println!("cargo:rerun-if-changed={generated}");
    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("options.rs");
    // DELETE FIRST. The file comes from the store and carries its read-only
    // mode with it; on the second generation `fs::copy` would fail with
    // "Permission denied" inside a build script.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} into OUT_DIR: {e}"));
}
